                  kind: unknown,
                  markdown: unknown,
                  metadata?: unknown,
                }> | null,
          markdown?: string,
          op: "insert_markdown",
        } | {
          block_id: string,
          block_kind?: "markdown" | "agent_instructions" | null,
          block_units?: Array<string | {
                  kind: unknown,
                  markdown: unknown,
                  metadata?: unknown,
                }> | null,
          expected_hash?: string | null,
          markdown?: string,
          op: "replace_block_markdown",
        } | {
          block_id: string,
          expected_hash?: string | null,
          op: "delete_block",
        } | {
          after_block_id: string | null,
          block_id: string,
          op: "move_block",
        } | {
          block_id: string,
          expected_hash?: string | null,
          metadata: {},
          op: "set_block_metadata",
        } | {
          at: {
              following_block_id: string | null,
              kind: "between_blocks",
              preceding_block_id: string | null,
            } | {
              anchor: {
                  kind: unknown,
                  relative_position_base64: unknown,
                } | {
                  expected_block_hash: unknown,
                  kind: unknown,
                  offset_utf16: unknown,
                },
              block_id: string,
              kind: "in_block",
            },
          label?: string,
          op: "insert_page_link",
          target_page_id: string,
        }>,
  page_id: string,
  stream_kind?: "content" | "scratch",
}): Promise<unknown>"
